const PLACE_DETAILS = {
 'edimburgo':{title:'Edimburgo',country:'Escocia',day:1,lead:'Una capital construida sobre un relieve extraordinario, donde la ciudad medieval y la gran ampliación georgiana se leen como dos capítulos de una misma historia.',sections:[
  ['Una ciudad nacida de un volcán','Castle Rock es el resto de un antiguo sistema volcánico. Mucho después, los glaciares erosionaron el terreno y dejaron una roca abrupta al oeste con una cresta alargada hacia el este. Sobre esa forma natural se desarrolló la ciudad medieval. La Royal Mile sigue, por tanto, una geografía que existía cientos de millones de años antes que Edimburgo.'],
  ['El castillo y el burgo medieval','La fortaleza convirtió el lugar en un centro político y militar. A sus pies creció un burgo real que se extendió por la cresta hacia Holyrood. Como el espacio útil era muy limitado, la ciudad creció hacia arriba y hacia dentro: edificios altos, patios y closes que descendían por las laderas. Esa densidad todavía se percibe al caminar por la Old Town.'],
  ['La Royal Mile','Castlehill, Lawnmarket, High Street y Canongate forman el eje entre el castillo y Holyroodhouse. En apenas una milla escocesa se concentran St Giles, antiguas casas nobles, edificios públicos y decenas de pasadizos. Caminarla es recorrer físicamente la transición desde la fortaleza a la residencia real.'],
  ['Una ciudad demasiado llena','En los siglos XVII y XVIII la Old Town sufría congestión, incendios y graves problemas sanitarios. Al norte, el Nor Loch había dejado de ser solo una defensa natural y se había convertido en una masa de agua insalubre. La élite urbana empezó a imaginar una expansión que reflejara nuevas ideas de orden, higiene y modernidad.'],
  ['La New Town','El plan de James Craig para la primera New Town fue aprobado en 1767. Calles rectas, plazas, jardines y fachadas georgianas ofrecían un contraste radical con el laberinto medieval. El Nor Loch fue drenado; su antigua depresión terminó ocupada por Princes Street Gardens y el corredor ferroviario. Desde los jardines se entiende perfectamente la enorme diferencia de cota con la Old Town.'],
  ['La Ilustración escocesa','Durante el siglo XVIII Edimburgo fue uno de los grandes centros intelectuales de Europa. David Hume, Adam Smith, James Hutton, Joseph Black y numerosos médicos, abogados y científicos compartían sociedades y debates. La ciudad combinó una escala relativamente pequeña con una concentración extraordinaria de talento y ganó el apodo de “Atenas del Norte”.'],
  ['Una ciudad literaria','Walter Scott contribuyó a construir una imagen romántica de la historia escocesa; Robert Louis Stevenson utilizó la ciudad como paisaje moral y emocional; Arthur Conan Doyle nació aquí y estudió medicina en su universidad. Esa tradición continúa en festivales, librerías y una intensa vida cultural.'],
  ['Qué mirar mientras caminamos','En la Old Town, levantad la vista hacia los edificios y fijaos en cómo los closes bajan desde la cresta. En Princes Street Gardens, mirad el castillo como una pared urbana suspendida sobre el parque. En la New Town, observad la regularidad de fachadas y perspectivas. Edimburgo se disfruta más leyendo esas relaciones que completando una lista de monumentos.'],
  ['Capital actual','Edimburgo es hoy capital política, cultural y administrativa de Escocia. El Parlamento escocés volvió a reunirse en 1999 y ocupa desde 2004 su edificio junto a Holyrood. Festivales, universidades, turismo, finanzas y administración conviven con un patrimonio excepcional que sigue formando parte de una ciudad viva.']
 ]},
 'castillo-de-edimburgo':{title:'Castillo de Edimburgo',country:'Escocia',day:1,lead:'Fortaleza, residencia real y símbolo nacional sobre Castle Rock.',sections:[
  ['Castle Rock','La roca del castillo es el resto resistente de un antiguo complejo volcánico. La erosión y los glaciares eliminaron materiales más blandos y dejaron una posición abrupta por tres lados, con un acceso más fácil desde el este. Esa combinación explica por qué el lugar tuvo un valor defensivo excepcional.'],
  ['Una fortaleza de muchas épocas','El conjunto no responde a un único proyecto. La capilla de Santa Margarita, del siglo XII, es el edificio conservado más antiguo; el Great Hall recuerda la etapa cortesana y real; y baterías, cuarteles y prisiones muestran el uso militar posterior. Recorrer el castillo es recorrer siglos de transformaciones.'],
  ['Las Honours of Scotland y la Stone of Destiny','Las joyas de la Corona escocesa se cuentan entre las insignias reales más antiguas conservadas en Europa. Junto a ellas se muestra la Stone of Destiny, vinculada durante siglos a las ceremonias de coronación de los reyes de Escocia.'],
  ['Qué no perderse','Crown Square, la capilla de Santa Margarita, el Great Hall y las vistas sobre la ciudad justifican la visita incluso si alguna de las zonas interiores tiene cola.']
 ]},
 'glen-coe':{title:'Glen Coe',country:'Escocia',day:2,lead:'Uno de los paisajes más poderosos de las Highlands, donde volcanismo antiguo, glaciaciones y memoria de los clanes se superponen.',sections:[
  ['Volcanes y hielo','Las rocas de Glen Coe están relacionadas con una gran estructura volcánica formada hace cientos de millones de años. Mucho después, los glaciares ocuparon el valle y excavaron su característica sección en U. El fondo relativamente abierto y las laderas que ascienden con brusquedad son algunas de las huellas más claras del trabajo del hielo.'],
  ['Three Sisters y Buachaille Etive Mòr','Las Three Sisters forman parte de la gran ladera de Bidean nam Bian. Buachaille Etive Mòr se alza como una pirámide a la entrada oriental del valle. Son imágenes muy conocidas, pero conviene mirar también cascadas, valles laterales suspendidos y cambios de vegetación, que cuentan la historia geológica del lugar.'],
  ['El mundo de los clanes','Antes de la modernización del Estado, gran parte de las Highlands se organizaba mediante redes de parentesco, jefaturas y lealtades territoriales. Los MacDonald de Glencoe eran una rama de uno de los grandes linajes del oeste. El clan era una estructura social y política, no simplemente una familia identificada por un tartán.'],
  ['La matanza de 1692','Tras la revolución que expulsó a Jacobo VII de Escocia, los jefes de clan debían jurar lealtad a los nuevos monarcas. Alastair MacIain de Glencoe presentó su juramento tarde. Soldados del Gobierno fueron alojados durante casi dos semanas por los MacDonald y recibieron después la orden de atacarlos. Murieron decenas de personas y otras fallecieron al huir en pleno invierno.'],
  ['Por qué el episodio dejó tanta huella','La matanza resultó especialmente escandalosa porque se produjo después de que los soldados hubieran aceptado hospitalidad. Esa ruptura de las normas tradicionales dio al episodio un enorme peso moral y lo convirtió en una de las historias más recordadas de las Highlands.'],
  ['Cuando estéis allí','No busquéis únicamente la foto de las Three Sisters. Observad la forma completa del valle y recordad que este paisaje fue hogar y territorio de pastoreo mucho antes de convertirse en icono turístico. La escala y el silencio son una parte esencial de la experiencia.']
 ]},
 'lago-ness':{title:'Lago Ness',country:'Escocia',day:2,lead:'Un lago célebre por Nessie, pero geológicamente mucho más interesante de lo que su leyenda sugiere.',sections:[
  ['El Great Glen','Loch Ness forma parte del Great Glen, una gran línea de fractura que atraviesa Escocia de suroeste a nordeste. Los glaciares aprovecharon esa debilidad de la corteza y profundizaron el valle, creando una cadena de lagos largos y estrechos.'],
  ['Agua oscura y gran profundidad','El color oscuro del agua se debe en parte a materia orgánica procedente de las turberas. Esa apariencia, combinada con la profundidad del lago y la frecuencia de nieblas, ha contribuido a la atmósfera que rodea las historias sobre el monstruo.'],
  ['Nessie','Los relatos modernos sobre una criatura en el lago adquirieron fama internacional en el siglo XX. No existe evidencia científica que demuestre la presencia de un gran animal desconocido, pero la leyenda se ha convertido en parte inseparable de la cultura popular de las Highlands.']
 ]},
 'dunnottar':{title:'Castillo de Dunnottar',country:'Escocia',day:3,lead:'Una fortaleza espectacular cuyo sistema defensivo más importante era el propio promontorio.',sections:[
  ['Una posición casi inexpugnable','Dunnottar ocupa una plataforma rocosa separada de tierra firme por un acceso estrecho y rodeada por acantilados sobre el Mar del Norte. La topografía permitía defender el lugar con relativamente pocos hombres. Antes de entrar, el primer mirador explica mejor que cualquier plano por qué se eligió esta posición.'],
  ['Siglos de edificios','Las ruinas actuales pertenecen a épocas distintas: fortificación, residencias, capilla, almacenes y dependencias militares. Dunnottar no fue un castillo diseñado de una vez, sino un pequeño conjunto que se transformó durante siglos según cambiaban propietarios, necesidades y técnicas de guerra.'],
  ['Wallace y la memoria medieval','La tradición vincula Dunnottar con William Wallace y las guerras contra Inglaterra a finales del siglo XIII. Como ocurre con muchas historias medievales, hechos y leyenda se mezclaron con el tiempo. Lo importante es recordar que dominar fortalezas como esta era esencial para controlar la costa oriental.'],
  ['Las Honours of Scotland','Ante el avance de las fuerzas de Oliver Cromwell en el siglo XVII, la corona, el cetro y la espada de Estado de Escocia fueron llevados a Dunnottar. Tras un largo asedio, lograron sacarse ocultos y permanecieron escondidos hasta la restauración de la monarquía.'],
  ['La Whigs Vault','Dunnottar conserva también una historia más oscura. En 1685 más de un centenar de Covenanters fueron encerrados en condiciones terribles en una bóveda del castillo. El lugar recuerda que las fortalezas no solo protegían: también servían para imponer poder y castigo.'],
  ['Cuando estéis allí','Quien no quiera bajar todos los escalones puede quedarse en los miradores sin perder la esencia de la visita. Si entráis, intentad imaginar el promontorio lleno de actividad: soldados, sirvientes, almacenes y habitaciones donde hoy solo vemos ruinas.']
 ]},
 'saint-andrews':{title:'Saint Andrews',country:'Escocia',day:3,lead:'Una pequeña ciudad cuya importancia histórica es enorme: gran centro religioso medieval, universidad más antigua de Escocia y capital simbólica del golf.',sections:[
  ['Antes del golf','Saint Andrews fue durante siglos el principal centro eclesiástico de Escocia y destino de peregrinación. La tradición vinculó el lugar a reliquias de san Andrés, que acabaría siendo patrón del país. Esa función religiosa explica la escala de la catedral y la influencia política de la ciudad.'],
  ['La catedral y la Reforma','La gran catedral fue una de las instituciones religiosas más poderosas del reino. La Reforma escocesa de 1560 cambió radicalmente su destino. El enorme recinto en ruinas permite imaginar el peso que tuvo antes de que la nueva Iglesia protestante transformara la vida religiosa.'],
  ['El castillo','El castillo fue residencia de obispos y escenario de conflictos religiosos. Durante un asedio del siglo XVI se excavaron una mina y una contramina, todavía conservadas, que muestran de manera extraordinaria cómo podía desarrollarse la guerra bajo tierra.'],
  ['La universidad','Fundada a comienzos del siglo XV, es la universidad más antigua de Escocia. Sus colegios y patios están integrados en el casco urbano, por lo que la universidad no se visita como un recinto separado: forma parte de la identidad cotidiana de Saint Andrews.'],
  ['Por qué el golf nació aquí','Los links son terrenos arenosos y ondulados junto al mar, poco aptos para la agricultura pero perfectos para un juego que aprovechaba dunas y depresiones naturales. El Old Course evolucionó con el uso y Saint Andrews ayudó después a fijar reglas y tradiciones del golf moderno.'],
  ['Old Course y West Sands','El pequeño Swilcan Bridge junto al hoyo 18 es una imagen universal del golf. West Sands muestra el paisaje costero que explica el origen de los links. Incluso para quien no tenga interés deportivo, merece la pena ver cómo ciudad, universidad y costa se encuentran en pocos minutos a pie.']
 ]},
 'anillo-de-kerry':{title:'Anillo de Kerry',country:'Irlanda',day:5,lead:'Una ruta panorámica por la península de Iveragh donde glaciares, montañas y Atlántico se suceden casi en cada curva.',sections:[
  ['La península de Iveragh','Iveragh está formada por antiguas rocas, especialmente areniscas, que fueron plegadas y elevadas mucho antes de las glaciaciones. Después, el hielo excavó valles y cubetas y el Atlántico recortó la costa. El resultado es un paisaje robusto de montañas, lagos, playas y cabos.'],
  ['Killarney','Los lagos de Killarney, los bosques de roble y tejo y las montañas forman uno de los paisajes más conocidos de Irlanda. La zona alberga además una importante población de ciervo rojo y conserva algunos de los bosques atlánticos más valiosos del país.'],
  ['Ladies View y Moll’s Gap','Ladies View permite contemplar los lagos desde una posición elevada. Moll’s Gap cambia el escenario hacia un paso de montaña más desnudo. En pocos kilómetros se aprecia cómo el paisaje de Kerry varía continuamente.'],
  ['Kenmare, Sneem y Cahersiveen','Kenmare aporta la escala de una pequeña localidad de mercado; Sneem, la imagen de un pueblo de casas de colores junto al río; Cahersiveen marca el sector occidental de nuestro recorrido y está ligado a Daniel O’Connell, gran figura política del siglo XIX.'],
  ['Una mañana muy concentrada','El Ring of Kerry suele ocupar un día completo. Nuestro itinerario lo concentra porque queremos estar en Cobh a las 15:00. Eso obliga a seleccionar: pocas paradas, tiempos cortos y atención constante al reloj. La carretera debe disfrutarse sin intentar convertir cada mirador en una visita.']
 ]},
 'cobh':{title:'Cobh',country:'Irlanda',day:5,lead:'Un puerto de casas de colores cuya historia está marcada por la emigración, el Titanic y el Lusitania.',sections:[
  ['Un gran puerto natural','Cobh se encuentra en Cork Harbour, uno de los mayores puertos naturales del mundo. La protección de la bahía y su profundidad explican su importancia naval y comercial. La localidad creció sobre las laderas de Great Island y parece descender hacia el agua.'],
  ['Queenstown','En 1849, tras una visita de la reina Victoria, la localidad fue rebautizada como Queenstown. Recuperó el nombre Cobh en 1920. Por eso los documentos de la Gran Hambruna, el Titanic y el Lusitania suelen referirse al lugar como Queenstown.'],
  ['La puerta de la emigración','Durante los siglos XIX y XX millones de irlandeses emigraron. Muchos salieron por este puerto, especialmente después de la Gran Hambruna. Para numerosas familias, Cobh fue la última imagen de Irlanda antes de iniciar una vida en Gran Bretaña, Estados Unidos, Canadá o Australia.'],
  ['El Titanic','El Titanic hizo aquí su última escala el 11 de abril de 1912. El gran buque permaneció fondeado y pequeñas embarcaciones trasladaron pasajeros, correo y equipaje. Cuatro días después se hundió en el Atlántico. Saberlo da una dimensión especial al paseo por el mismo puerto desde el que partieron aquellos pasajeros.'],
  ['El Lusitania','En 1915 el transatlántico Lusitania fue torpedeado por un submarino alemán frente a la costa de Cork. Supervivientes y cuerpos fueron llevados a Queenstown. El desastre volvió a situar este puerto en el centro de un acontecimiento internacional y dejó una profunda memoria local.'],
  ['St Colman Cathedral','La catedral católica de St Colman, construida entre los siglos XIX y XX, se alza sobre la ladera con una gran aguja neogótica. El contraste entre el edificio monumental, las calles empinadas y las fachadas de colores forma la imagen más reconocible de Cobh.'],
  ['Una tarde mejor que una visita de paso','El cambio de itinerario beneficia mucho a Cobh. Después de Kerry podremos bajar el ritmo, recorrer el paseo marítimo, subir hacia la catedral y cenar en la ciudad. Es un lugar que gana cuando se dispone de tiempo para mirar el puerto y pensar en su historia.']
 ]},
 'blarney-castle':{title:'Blarney Castle & Gardens',country:'Irlanda',day:6,lead:'Mucho más que la piedra famosa: una gran casa-torre gaélica rodeada de jardines y leyendas.',sections:[
  ['Los MacCarthy','La torre principal fue construida en el siglo XV por los MacCarthy de Muskerry. Como otras tower houses irlandesas, combinaba residencia, representación y defensa. Las escaleras estrechas y los espacios superpuestos recuerdan que la seguridad pesaba tanto como la comodidad.'],
  ['La Piedra de Blarney','La tradición afirma que besar la piedra concede el “gift of the gab”, el don de la elocuencia. Existen varias leyendas sobre su origen y ninguna explicación histórica definitiva. Hoy el ritual forma parte inseparable de la visita, pero no debería eclipsar el propio castillo.'],
  ['Rock Close','Rock Close mezcla árboles, roca, agua y relatos de druidas, brujas y seres del folclore. Muchas asociaciones son románticas y relativamente modernas, pero el lugar ofrece un paseo muy distinto de la subida a la torre.'],
  ['Los jardines','La finca es extensa y cuenta con numerosos senderos y jardines. Nuestro horario obliga a seleccionar: torre y piedra para quien quiera la experiencia clásica; Rock Close y jardines próximos para quienes prefieran una visita más tranquila.']
 ]},
 'king-john-s-castle':{title:'King John\'s Castle',country:'Irlanda',day:6,lead:'Una gran fortaleza normanda sobre el Shannon, clave para comprender la importancia estratégica de Limerick.',sections:[
  ['Limerick y el Shannon','Limerick se desarrolló en un punto estratégico del río Shannon. Hubo un asentamiento vikingo y después un importante núcleo normando. Controlar el puente y la navegación significaba dominar una de las principales rutas del oeste de Irlanda.'],
  ['La fortaleza normanda','El castillo se levantó a comienzos del siglo XIII durante el reinado de Juan de Inglaterra. Sus torres y murallas responden a una arquitectura militar de gran escala, muy distinta de las casas-torre gaélicas que veremos en Blarney.'],
  ['Los asedios','Limerick desempeñó un papel decisivo en las guerras del siglo XVII. Los asedios de 1690 y 1691 terminaron con el Tratado de Limerick, que marcó el final de la resistencia jacobita organizada en Irlanda y dejó una memoria política muy duradera.'],
  ['Nuestra visita','Nos centraremos en el castillo y en su relación con el río. No intentaremos recorrer la ciudad: Bunratty tiene una hora límite y debe conservarse margen suficiente para llegar antes de las 16:00.']
 ]},
 'bunratty-castle-y-folk-park':{title:'Bunratty Castle & Folk Park',country:'Irlanda',day:6,lead:'Un castillo del siglo XV y un parque de historia social que permiten pasar de las élites medievales a la vida cotidiana irlandesa.',sections:[
  ['Un lugar estratégico','Bunratty se encuentra cerca del estuario del Shannon, en una zona importante para las comunicaciones entre Limerick, Clare y la costa. Hubo fortificaciones anteriores, pero el gran castillo actual fue levantado en el siglo XV y estuvo vinculado a los MacNamara y después a los O’Brien.'],
  ['Castillo y residencia','Sus torres y gran bloque central muestran cómo una residencia aristocrática podía combinar defensa y representación. Los interiores amueblados permiten imaginar el edificio como una casa habitada, no simplemente como una ruina romántica.'],
  ['El Folk Park','El parque reúne y recrea casas rurales, tiendas, escuela, iglesia y otros edificios de los siglos XIX y principios del XX. Después de visitar castillos, es una oportunidad excelente para acercarse a la vida cotidiana de agricultores, artesanos y comerciantes.'],
  ['La hora manda','La última entrada indicada es a las 16:00. Esa referencia debe gobernar toda la jornada. Una vez dentro podremos administrar el tiempo, pero llegar tarde significaría perder una de las nuevas visitas más interesantes del itinerario.']
 ]},
 'galway':{title:'Galway',country:'Irlanda',day:7,lead:'Una ciudad atlántica de raíces medievales que se disfruta tanto por su historia como por la música, las calles y el ambiente.',sections:[
  ['Puerto medieval','Galway creció como ciudad amurallada y puerto comercial. Su posición en la desembocadura del Corrib facilitó relaciones con Gran Bretaña, Francia y la península ibérica. El centro actual conserva la escala compacta de aquella ciudad mercantil.'],
  ['Las Tribes of Galway','Durante siglos un grupo de familias mercantiles dominó la política urbana. Más tarde serían conocidas como las Fourteen Tribes of Galway. El término nació como una burla, pero terminó adoptándose con orgullo. Lynch’s Castle recuerda todavía la riqueza y poder de esas familias.'],
  ['España y el Spanish Arch','El comercio con la península ibérica fue importante. El Spanish Arch no fue construido por españoles: formaba parte de las defensas junto a los muelles. Su nombre posterior refleja la memoria de esos vínculos marítimos.'],
  ['Claddagh','Al otro lado del Corrib estaba Claddagh, una comunidad pesquera con fuerte identidad propia. Su nombre está asociado al famoso anillo de dos manos que sostienen un corazón coronado, símbolo de amistad, amor y lealtad.'],
  ['Música y cultura','Galway es una puerta natural hacia Connemara y hacia regiones donde el irlandés conserva presencia. Universidad, festivales, teatro y música tradicional dan a la ciudad una vida cultural muy intensa. La música callejera de Shop Street y Quay Street es parte de esa identidad.'],
  ['Qué ver sin convertirlo en una carrera','Eyre Square, Shop Street, Lynch’s Castle, St Nicholas, Quay Street y Spanish Arch forman un recorrido compacto. La catedral y la ribera del Corrib pueden añadirse con facilidad. Pero Galway se disfruta mejor dejando huecos: una tienda, un músico o un pub pueden ser tan memorables como un monumento.'],
  ['La ventaja del nuevo itinerario','Disponer de la tarde completa después de Moher es una gran mejora. Podremos comer, dividirnos por familias y volver a reunirnos más tarde. La ciudad necesita precisamente ese tipo de visita flexible.']
 ]},
 'el-burren':{title:'El Burren',country:'Irlanda',day:7,lead:'Un paisaje calizo aparentemente desnudo que esconde una extraordinaria diversidad natural y una larga presencia humana.',sections:[
  ['Un paisaje kárstico','La superficie está formada por grandes losas de caliza separadas por grietas. El agua se infiltra con rapidez y circula bajo tierra, creando cavidades, cuevas y conductos. Esa falta de agua superficial contribuye a la apariencia austera del territorio.'],
  ['Una flora inesperada','En las grietas protegidas crecen especies que normalmente asociaríamos a regiones muy diferentes. Plantas atlánticas, alpinas y mediterráneas pueden encontrarse muy próximas entre sí gracias a la combinación de microclimas, roca caliza y prácticas ganaderas tradicionales.'],
  ['Paisaje cultural','Muros de piedra seca, restos arqueológicos y pequeñas explotaciones recuerdan que el Burren no es un espacio vacío. Las comunidades humanas se han adaptado durante milenios a un suelo que a primera vista parece poco favorable.']
 ]},
 'acantilados-de-moher':{title:'Acantilados de Moher',country:'Irlanda',day:7,lead:'Una pared de roca frente al Atlántico donde la geología, el viento y las aves forman una sola experiencia.',sections:[
  ['Cómo se formaron','Los acantilados están compuestos por capas de areniscas, limos y lutitas depositadas hace cientos de millones de años. La erosión marina socava la base y abre fracturas; los desprendimientos resultantes mantienen el frente abrupto.'],
  ['Una colonia de aves marinas','Los cortados ofrecen lugares de nidificación inaccesibles para muchos depredadores. En temporada pueden verse fulmares, araos, alcas y, con algo de suerte, frailecillos. Unos pequeños prismáticos ayudan mucho más que acercarse al borde.'],
  ['La experiencia depende del tiempo','Sol, lluvia, niebla y viento cambian por completo la percepción del lugar. La roca puede pasar del ocre al gris casi negro en minutos. No hace falta un cielo despejado para disfrutar de Moher: el mal tiempo puede intensificar su carácter atlántico.']
 ]},
 'dublin':{title:'Dublín',country:'Irlanda',day:8,lead:'Una capital junto al Liffey donde se superponen herencias vikingas, medievales, británicas, independentistas y literarias.',sections:[
  ['Dos nombres para una ciudad','Dublin procede de Dubh Linn, “laguna negra”. El nombre irlandés, Baile Átha Cliath, recuerda el asentamiento del vado. Ambos nombres reflejan dos núcleos próximos que terminaron formando la ciudad. El Liffey y el acceso al mar fueron determinantes desde el principio.'],
  ['La ciudad vikinga','Los vikingos establecieron un asentamiento permanente en el siglo IX y convirtieron Dublín en un importante centro comercial. Sus conexiones alcanzaban Gran Bretaña, Escandinavia y el Atlántico. El entorno de Christ Church se encuentra en el corazón de aquella ciudad medieval que creció sobre bases vikingas.'],
  ['Dublin Castle','Después de la conquista anglonormanda, Dublín se convirtió en centro del poder inglés en Irlanda. Dublin Castle, iniciado a comienzos del siglo XIII, fue durante siglos sede de administración y gobierno. En 1922 fue entregado al nuevo Estado Libre Irlandés, un gesto cargado de simbolismo.'],
  ['La ciudad georgiana','En el siglo XVIII Dublín experimentó una gran expansión. Plazas, casas de ladrillo, puertas de colores y amplias calles crearon la imagen georgiana visible en Merrion Square o Fitzwilliam Square. En aquella época era una de las grandes ciudades del Imperio británico y sede de un Parlamento irlandés hasta 1801.'],
  ['Trinity College y el Book of Kells','Trinity College fue fundado en 1592. Su biblioteca conserva el Book of Kells, manuscrito iluminado realizado alrededor del año 800 y una de las grandes obras del arte medieval europeo. Nuestro tiempo puede impedir una visita interior, pero el lugar explica parte del prestigio cultural de Dublín.'],
  ['1916 e independencia','La ciudad fue escenario central del Levantamiento de Pascua de 1916 y del proceso que condujo a la independencia. El General Post Office quedó ligado a la rebelión y Dublin Castle simbolizaba la administración británica. Edificios y monumentos de la capital conservan memorias políticas muy diferentes.'],
  ['Una ciudad literaria','Swift, Wilde, Yeats, Joyce y Beckett son algunos de los escritores ligados a Dublín. Joyce convirtió calles, pubs y ciudadanos corrientes en literatura universal. La UNESCO reconoce a Dublín como Ciudad de la Literatura. Su identidad cultural depende tanto de los libros y el teatro como de los monumentos.'],
  ['Temple Bar con perspectiva','Temple Bar es conocido por los pubs, pero también concentra instituciones culturales y una trama de calles que merece recorrerse temprano. En nuestro paseo exprés funciona como enlace natural entre Dublin Castle y el Liffey.'],
  ['Una primera impresión, no una visita completa','El último día es muy corto. No intentaremos “hacer Dublín”. Christ Church, Dublin Castle, Dame Street y el borde de Temple Bar son suficientes para obtener una primera impresión sin comprometer el vuelo. La ciudad merece otra visita en el futuro.']
 ]}
};


const DETAIL_ALIASES={
 'killarney-national-park':'anillo-de-kerry','ladies-view':'anillo-de-kerry','moll-s-gap':'anillo-de-kerry','kenmare':'anillo-de-kerry','sneem':'anillo-de-kerry','cahersiveen':'anillo-de-kerry',
 'king-john-s-castle':'king-john-s-castle','bunratty-castle-y-folk-park':'bunratty-castle-y-folk-park',
 'latin-quarter-y-quay-street':'galway','spanish-arch-y-claddagh':'galway'
};

function slugify(s){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/&/g,'y').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function routeLink(n){const r=ROUTES[n]; if(!r) return null; const p=r.points; const origin=p[0], destination=p[p.length-1], waypoints=p.slice(1,-1).join('|'); return `https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(origin)}&destination=${encodeURIComponent(destination)}${waypoints?`&waypoints=${encodeURIComponent(waypoints)}`:''}&travelmode=${r.mode}`;}
function detailSlug(name){const slug=slugify(name);return PLACE_DETAILS[slug]?slug:(DETAIL_ALIASES[slug]||null);}
function detailFor(name){const slug=detailSlug(name);return slug?PLACE_DETAILS[slug]:null;}

function mapsLink(q){return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(q)}`}
function todayNumber(){const now=new Date(); if(now.getFullYear()!==2026||now.getMonth()!==7) return null; const d=now.getDate(); return d>=13&&d<=20?d-12:null;}
function dayCard(d){const today=todayNumber()===d.n?' today':'';return `<a class="card day-card${today}" href="#dia-${d.n}"><div class="day-number">Día ${d.n} · ${d.date}</div><h3>${d.title}</h3><p>${d.subtitle}</p><div class="badges">${d.tags.map(t=>`<span class="badge">${t}</span>`).join('')}</div></a>`}
function renderHome(){const t=todayNumber(),hero=PHOTOS[1];return `<section class="hero hero-photo" id="inicio" style="--hero-image:url('${hero.url}')"><div class="hero-inner"><div class="eyebrow">13–20 agosto 2026 · 23 viajeros</div><h1>Escocia e Irlanda en familia</h1><p>Guía digital ampliada con itinerario, rutas, historia, lugares, hoteles y datos prácticos para leer y consultar antes y durante el viaje.</p><div class="hero-actions"><a class="btn" href="#dias">Ver los 8 días</a><a class="btn secondary" href="#historia">Historia y contexto</a></div><div class="stats"><div class="stat"><strong>8</strong><span>días</span></div><div class="stat"><strong>2</strong><span>países</span></div><div class="stat"><strong>23</strong><span>viajeros</span></div><div class="stat"><strong>5</strong><span>coches en Irlanda</span></div></div><div class="photo-credit"><a href="${hero.source}" target="_blank">Foto: ${hero.credit}</a></div></div></section>${t?`<section class="container"><div class="today-panel"><div class="card today-main"><div class="eyebrow">Hoy toca</div><h2>Día ${t} · ${DAYS[t-1].title}</h2><p>${DAYS[t-1].summary}</p><a class="btn secondary" href="#dia-${t}">Abrir jornada</a></div><div class="card today-side"><div><div class="day-number">Dormimos en</div><div class="big">${DAYS[t-1].sleep}</div></div><div class="muted">${DAYS[t-1].date}</div></div></div></section>`:''}<section class="container"><div class="section-title"><div><div class="eyebrow" style="color:var(--accent-2)">Mapa general</div><h2>La ruta completa</h2></div><p>Mapa interactivo orientativo de Escocia e Irlanda.</p></div><div class="map-card"><div id="tripMap" class="map"></div></div></section><section class="container" id="dias"><div class="section-title"><div><div class="eyebrow" style="color:var(--accent-2)">Itinerario</div><h2>El viaje de un vistazo</h2></div><p>Toca cualquier jornada para abrir horarios, lugares, contexto y recomendaciones.</p></div><div class="grid">${DAYS.map(dayCard).join('')}</div></section><section class="container home-links"><div class="grid"><a class="card feature-link" href="#historia"><div class="day-number">Antes de viajar</div><h3>Historia de Escocia e Irlanda</h3><p>Dos introducciones pensadas para entender mejor lo que iremos viendo.</p></a><a class="card feature-link" href="#lugares"><div class="day-number">Lectura</div><h3>Lugares del viaje</h3><p>Fichas ampliadas para leer antes de cada parada.</p></a><a class="card feature-link" href="#hoteles"><div class="day-number">Alojamiento</div><h3>Hoteles y datos de contacto</h3><p>Direcciones, teléfonos, noches y acceso rápido a Google Maps.</p></a></div></section>`}
function renderDay(n){
 const d=DAYS.find(x=>x.n===n)||DAYS[0],ph=PHOTOS[d.n],route=routeLink(d.n);
 return `<section class="day-hero day-photo" style="--day-image:url('${ph.url}')"><div class="container"><a class="back" href="#dias">← Todos los días</a><div class="eyebrow">Día ${d.n} · ${d.date} · Noche: ${d.sleep}</div><h1>${d.title}</h1><p>${d.subtitle}</p><div class="day-progress"><span style="width:${d.n/8*100}%"></span></div><div class="photo-credit"><a href="${ph.source}" target="_blank">Foto: ${ph.credit}</a></div></div></section><section class="container"><div class="card"><h2>Resumen del día</h2><p>${d.summary}</p></div><div class="section-title"><div><div class="eyebrow" style="color:var(--accent-2)">Ruta</div><h2>Mapa de la jornada</h2></div><p>Marcadores orientativos de las principales paradas.</p></div><div class="map-card"><div id="dayMap" class="map day-map"></div></div>${route?`<div class="actions route-actions"><a class="btn" target="_blank" rel="noopener" href="${route}">🧭 Abrir ruta del día en Google Maps</a></div>`:`<div class="callout compact"><strong>Ruta del día</strong>Este día combina desplazamientos urbanos, traslado al aeropuerto y vuelo; no se representa como una única ruta de carretera.</div>`}<div class="section-title"><h2>Horario</h2></div><div class="card schedule">${d.schedule.map(r=>`<div class="schedule-row"><div class="time">${r[0]}</div><div>${r[1]}</div></div>`).join('')}</div><div class="section-title"><div><h2>Lugares</h2></div><p>Resumen para la jornada. Las fichas ampliadas permiten leer con más calma antes de llegar.</p></div>${d.places.map(p=>{const det=detailFor(p[0]);return `<article class="card place"><h3>${p[0]}</h3><p>${p[1]}</p><div class="actions">${det?`<a class="btn" href="#lugar-${detailSlug(p[0])}">Leer más →</a>`:''}<a class="btn secondary" target="_blank" rel="noopener" href="${mapsLink(p[0])}">📍 Abrir en Maps</a></div></article>`}).join('')}<div class="callout"><strong>Cinco minutos antes de llegar</strong>${d.before}</div><div class="callout"><strong>Si solo pudiera recomendar una cosa de hoy…</strong>${d.recommend}</div><div class="actions"><a class="btn secondary" href="#dia-${Math.max(1,n-1)}">← Día anterior</a><a class="btn" href="#dia-${Math.min(8,n+1)}">Día siguiente →</a></div></section>`
}
function renderPlaces(){const entries=Object.entries(PLACE_DETAILS);return `<section class="page-head"><div class="container"><div class="eyebrow">Para leer antes de llegar</div><h1>Lugares del viaje</h1><p>Fichas más amplias para quienes quieran conocer la historia, el paisaje y el contexto de cada parada.</p></div></section><section class="container"><div class="places-index">${entries.map(([slug,p])=>`<a class="card place-index-card" href="#lugar-${slug}"><div class="day-number">${p.country} · Día ${p.day}</div><h3>${p.title}</h3><p>${p.lead}</p><span class="text-link">Leer ficha →</span></a>`).join('')}</div></section>`}
function renderPlace(slug){const p=PLACE_DETAILS[slug]; if(!p)return renderPlaces(); return `<section class="page-head place-head"><div class="container"><a class="back" href="#dia-${p.day}">← Volver al Día ${p.day}</a><div class="eyebrow">${p.country} · Día ${p.day}</div><h1>${p.title}</h1><p>${p.lead}</p><div class="actions"><a class="btn" target="_blank" rel="noopener" href="${mapsLink(p.title)}">📍 Abrir en Maps</a></div></div></section><section class="container reading">${p.sections.map(s=>`<article class="card reading-section"><h2>${s[0]}</h2><p>${s[1]}</p></article>`).join('')}<div class="actions"><a class="btn secondary" href="#dia-${p.day}">← Volver a la jornada</a><a class="btn" href="#lugares">Todas las fichas</a></div></section>`}
function historyBlock(key){const h=HISTORY[key];return `<article class="history-block"><div class="day-number">${key==='scotland'?'Escocia':'Irlanda'}</div><h2>${h.title}</h2><p class="history-intro">${h.intro}</p>${h.sections.map(s=>`<section class="card history-section"><h3>${s[0]}</h3><p>${s[1]}</p></section>`).join('')}</article>`}
function renderHistory(){return `<section class="page-head"><div class="container"><div class="eyebrow">Contexto</div><h1>Historia para entender el viaje</h1><p>No es un manual de historia: son las claves necesarias para que castillos, ciudades y paisajes tengan más sentido cuando estemos allí.</p></div></section><section class="container history-wrap">${historyBlock('scotland')}${historyBlock('ireland')}</section>`}
function renderHotels(){return `<section class="page-head"><div class="container"><div class="eyebrow">Alojamiento</div><h1>Hoteles</h1><p>Información de consulta rápida durante el viaje.</p></div></section><section class="container" id="hoteles"><div class="grid">${HOTELS.map(h=>`<article class="card hotel-card"><div class="day-number">${h.city}</div><h3>${h.name}</h3><div class="hotel-meta"><div>${h.address}</div><div><strong>Noches:</strong> ${h.nights}</div>${h.phone?`<div><strong>Tel.</strong> ${h.phone}</div>`:''}${h.email?`<div><strong>Email.</strong> ${h.email}</div>`:''}<div class="hotel-note">${h.note}</div></div><div class="actions"><a class="btn" target="_blank" rel="noopener" href="${mapsLink(h.name+' '+h.address)}">📍 Maps</a>${h.phone?`<a class="btn secondary" href="tel:${h.phone.replace(/\s/g,'')}">☎ Llamar</a>`:''}</div></article>`).join('')}</div></section>`}
function renderPractical(){return `<section class="page-head"><div class="container"><div class="eyebrow">Consulta rápida</div><h1>Información práctica</h1><p>Lo esencial para tener a mano sin abrir el documento Word.</p></div></section><section class="container" id="practico"><div class="quick-list">${practical.map(p=>`<div class="quick-item"><strong>${p[0]}</strong><div class="muted">${p[1]}</div></div>`).join('')}</div></section>`}
function baseMap(id){if(typeof L==='undefined')return null;return L.map(id,{scrollWheelZoom:false})}
function addTiles(m){L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(m)}
function initTripMap(){const el=document.getElementById('tripMap');if(!el||el._leaflet_id)return;const m=baseMap('tripMap');if(!m)return;addTiles(m);const pts=[[55.9533,-3.1883],[56.6826,-5.1023],[57.4778,-4.2247],[56.945,-2.197],[56.3398,-2.7967],[51.8985,-8.4756],[51.9668,-9.5931],[51.8507,-8.294],[53.2707,-9.0568],[52.9715,-9.4309],[53.3498,-6.2603]];L.polyline(pts,{color:'#b88b4a',weight:3,opacity:.8,dashArray:'8 8'}).addTo(m);[['Edimburgo',55.9533,-3.1883],['Cork',51.8985,-8.4756],['Galway',53.2707,-9.0568],['Dublín',53.3498,-6.2603]].forEach(p=>L.marker([p[1],p[2]]).addTo(m).bindPopup(`<strong>${p[0]}</strong>`));m.fitBounds(pts,{padding:[25,25]})}
function initDayMap(n){const el=document.getElementById('dayMap');if(!el||el._leaflet_id)return;const data=DAY_POINTS[n]||[],m=baseMap('dayMap');if(!m)return;addTiles(m);const pts=data.map(p=>[p[1],p[2]]);L.polyline(pts,{color:'#b88b4a',weight:4,opacity:.9}).addTo(m);data.forEach((p,i)=>L.marker([p[1],p[2]]).addTo(m).bindPopup(`<strong>${i+1}. ${p[0]}</strong>`));m.fitBounds(pts,{padding:[25,25]})}
function renderCredits(){const uniq=Object.values(PHOTOS).filter((x,i,a)=>a.findIndex(y=>y.source===x.source)===i);return `<section class="page-head"><div class="container"><div class="eyebrow">Imágenes y cartografía</div><h1>Créditos</h1><p>Fotografías de Wikimedia Commons y mapas de OpenStreetMap.</p></div></section><section class="container"><div class="grid">${uniq.map(p=>`<article class="card credit-card"><img src="${p.url}" alt="${p.caption}" loading="lazy"><h3>${p.caption}</h3><p class="muted">${p.credit}</p><a class="btn secondary" target="_blank" href="${p.source}">Ver ficha y licencia</a></article>`).join('')}</div><div class="callout"><strong>Cartografía</strong>Leaflet + OpenStreetMap. Las líneas de ruta son orientativas; para navegación real, usar Google Maps.</div></section>`}
function router(){let h=location.hash||'#inicio';document.getElementById('mainNav').classList.remove('open');if(h.startsWith('#dia-')){const n=Number(h.split('-')[1]);document.getElementById('app').innerHTML=renderDay(n);setTimeout(()=>initDayMap(n),50);}else if(h==='#dias'){document.getElementById('app').innerHTML=renderHome();setTimeout(()=>{initTripMap();document.getElementById('dias')?.scrollIntoView();},50);}else if(h.startsWith('#lugar-')){document.getElementById('app').innerHTML=renderPlace(h.slice(7));}else if(h==='#lugares'){document.getElementById('app').innerHTML=renderPlaces();}else if(h==='#historia'){document.getElementById('app').innerHTML=renderHistory();}else if(h==='#hoteles'){document.getElementById('app').innerHTML=renderHotels();}else if(h==='#practico'){document.getElementById('app').innerHTML=renderPractical();}else if(h==='#creditos'){document.getElementById('app').innerHTML=renderCredits();}else{document.getElementById('app').innerHTML=renderHome();setTimeout(initTripMap,50);}window.scrollTo(0,0)}
document.getElementById('menuBtn').addEventListener('click',()=>document.getElementById('mainNav').classList.toggle('open'));
window.addEventListener('hashchange',router);router();